// Press-kit content for the EPK (/booking): copy-ready bio and download files.
// Download files live in public/press/ (generated by `npm run press`, photo list in scripts/press.mjs).
import type { Lang } from "@/i18n/LanguageContext";

/**
 * EPK bio: single source for the text shown on /booking AND the "copy bio" button,
 * so what people see is exactly what they copy. One string per paragraph.
 */
export const bios: Record<Lang, string[]> = {
    de: [
        "Ansässig in München liefern Last Cats on Earth einen energiereichen Mix aus Hard Rock, Funk und Alternative Rock. Unsere wichtigste Regel ist Originalität: Egal ob eigene Tracks oder Neuinterpretationen bekannter Cover, wir machen es immer auf unsere Art.",
        "Unsere DNA ist stark vom kalifornischen Pop-Rock der frühen 2000er geprägt, mit Einflüssen aus Funk, Rap, Punk und elektronischer Musik. Nach FLASHBACK! und NEVER STOP ist UNDERWATER unsere neueste Single – und weitere Songs sind schon in der Pipeline.",
        "Von Club-Gigs bis zu Festival-Bühnen: Unsere Shows wechseln ständig den Gang – mit harten Instrumentals, Rap-Versen, Choreografien und direkter Interaktion mit dem Publikum.",
        "Wir machen nicht einfach nur Musik: Die Bühne ist unser Zuhause.",
    ],
    en: [
        "Based in Munich, Last Cats on Earth deliver a high-octane mix of hard rock, funk, and alternative rock sounds. Our main rule is originality: whether it's our original tracks or reinterpreting famous covers, we always do it our own way.",
        "Our DNA is heavily influenced by the Californian pop-rock of the early 2000s, reworking those sounds with influences from funk, rap, punk, and electronic music. After FLASHBACK! and NEVER STOP, UNDERWATER is our latest single – with more songs already in the pipeline.",
        "From intimate venues to bigger festival stages, our live shows keep everyone on their toes by constantly shifting gears: from hard-hitting instrumentals and melodic hooks to rap verses, choreography, and direct crowd interaction.",
        "We don't just play music: the stage is our home.",
    ],
};

/** Plain-text bio as copied to the clipboard. */
export const bioText = (lang: Lang) => bios[lang].join("\n\n");

export const pressFiles = {
    zip: "/press/last-cats-on-earth-presskit.zip",
    logo: "/press/last-cats-on-earth-logo.png",
    logoRound: "/press/last-cats-on-earth-logo-round.png",
    /** One-page band info (DE). */
    bandinfo: "/press/last-cats-on-earth-bandinfo.pdf",
    /** Generic tech rider incl. stage plot (page 1 DE, page 2 EN) – adapted per show. */
    rider: { de: "/press/last-cats-on-earth-tech-rider.pdf", en: "/press/last-cats-on-earth-tech-rider.pdf" } as Record<"de" | "en", string | null>,
};
